    if not string:
        return count
    if string[0] == '(':
        try:
            inner_level = recurse(string[1:])
            count = max(inner_level + count, count)
        except ValueError:
            return count

        string = string[1:]
        # Remove inner parentheses that may have been appended due to exceptions
        while not string or string[0] != ')':
            count -= 1
            string = string[1:]
        return recurse(string[1:])
    else:
        return recurse(string[1:])

