def get_range(numbers: List[int], lower: int, upper: int) -> List[int]:
    """ Given a range of numbers that can occur both in upper and lower part of list,
    Filter only the number that matches upper or lower parts of list
    """
    results = []

    for x in numbers:
        if lower > upper:
            if x >= lower:
                results.append(x)
        else:
            if x >= upper:
                results.append(x)

    return results




